resolved as (
  select u.id as university_id, src.category, src.title, src.description,
         src.link_title, src.link_url, src.link_type,
         src.contact_type, src.contact_value, src.contact_label
  from src
  join universities u on u.name = src.university_name and u.country_code = 'CZ'
)
insert into university_resources (
  university_id, category, title, description,
  link_title, link_url, link_type, contact_type, contact_value, contact_label
)
select university_id, category, title, description,
       link_title, link_url, link_type, contact_type, contact_value, contact_label
from resolved
on conflict (university_id, category) do nothing;
